export function haversine(a,b){const rad=Math.PI/180,dlat=(b.lat-a.lat)*rad,dlon=(b.lng-a.lng)*rad;const v=Math.sin(dlat/2)**2+Math.cos(a.lat*rad)*Math.cos(b.lat*rad)*Math.sin(dlon/2)**2;return 6371*2*Math.atan2(Math.sqrt(v),Math.sqrt(Math.max(0,1-v)))}
export function routeFromOrigin(route,origin){if(!origin)return {...route};const approach=haversine(origin,route);const localKm=Math.round(route.km*.22);const km=Math.max(12,Math.round(approach*2*1.18+localKm));const minutes=Math.ceil((km/55*60+route.walk+15)/5)*5;return {...route,km,minutes,approach,spots:[[origin.label+' 출발','현재 출발 위치에서 추천 코스 방향으로 달려요.'],...route.spots.slice(1,-1) , [origin.label+' 복귀','출발했던 곳으로 돌아오는 예시 일정이에요.']]}}
export function classifyWeather(code){return code<=1?'sunny':code<=3||code===45||code===48?'cloudy':'rainy'}
export function weatherIsSevere(code){return code>=95||[56,57,66,67,71,73,75,77,85,86].includes(code)}
export function departureTimestamp(mode,now=Date.now()){if(mode==='now')return now;const date=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(now));const hour={morning:'09',afternoon:'14',sunset:'17'}[mode]||'09';let t=new Date(`${date}T${hour}:00:00+09:00`).getTime();if(t<now)t+=86400000;return t}
export function weatherAt(series,timestamp){const h=series?.hourly;if(!h?.time?.length)return null;const t=timestamp/1000;let i=0;for(let j=1;j<h.time.length;j++)if(Math.abs(h.time[j]-t)<Math.abs(h.time[i]-t))i=j;const code=h.weather_code[i];if(!Number.isFinite(h.temperature_2m[i])||!Number.isFinite(h.wind_speed_10m[i]))return null;return {temp:Math.round(h.temperature_2m[i]),wind:Math.round(h.wind_speed_10m[i]*10)/10,weather:classifyWeather(code),severe:weatherIsSevere(code),time:h.time[i]*1000}}
